import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Accessibilità client desktop: copertura automatica e checklist manuale","description":"","frontmatter":{},"headers":[],"relativePath":"qa/a11y-desktop.md","filePath":"qa/a11y-desktop.md"}'),n={name:"qa/a11y-desktop.md"};function c(l,e,r,d,s,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="accessibilita-client-desktop-copertura-automatica-e-checklist-manuale" tabindex="-1">Accessibilità client desktop: copertura automatica e checklist manuale <a class="header-anchor" href="#accessibilita-client-desktop-copertura-automatica-e-checklist-manuale" aria-label="Permalink to &quot;Accessibilità client desktop: copertura automatica e checklist manuale&quot;">​</a></h1><p>Obiettivo: WCAG 2.1 AA per la <strong>chrome dell&#39;app</strong> (barre, pannelli, dialog, menu). Non si afferma conformità: sono riportate le misure e i limiti.</p><h2 id="copertura-automatica" tabindex="-1">Copertura automatica <a class="header-anchor" href="#copertura-automatica" aria-label="Permalink to &quot;Copertura automatica&quot;">​</a></h2><p>Suite Playwright sul mock dei binding Wails (<code>task e2e</code>, oppure <code>yarn workspace @clarae/desktop-frontend e2e a11y keyboard</code>):</p><ul><li><code>apps/desktop/frontend/e2e/a11y.spec.ts</code>: scansioni axe (<code>wcag2a, wcag2aa, wcag21a, wcag21aa</code>, blocca su <code>serious</code>/<code>critical</code>), in tema chiaro e scuro e con <code>prefers-reduced-motion: reduce</code>, di: schermata di benvenuto, shell con nota aperta e schede della barra laterale (File, Cerca, Tag, Struttura), palette comandi, selettore rapido, impostazioni, impostazioni scorciatoie, procedura di collegamento al cloud, condivisione e inviti, importer, vista grafo, nuova base, recupero file. <code>AXE_REPORT=&lt;file&gt;</code> salva tutte le violazioni (anche minori) in JSON lines.</li><li><code>apps/desktop/frontend/e2e/keyboard.spec.ts</code>: schede della barra laterale (roving tabindex, frecce, <code>Home</code>), albero dei file (una sola sosta, frecce/<code>Home</code>/<code>End</code>, espandi/chiudi, <code>Invio</code>, <code>F2</code>, menu con tasto Menu, ritorno del focus), schede dei documenti (frecce, <code>Canc</code>), palette come combobox.</li><li>Unit: <code>src/i18n/lang.test.ts</code> (<code>&lt;html lang&gt;</code> segue la lingua).</li></ul><p><strong>Contenuto dell&#39;editor:</strong> <code>.cm-content</code> (Sorgente) e il canvas Excalidraw sono <strong>esclusi</strong> dalla scansione (il loro modello DOM non è sotto il nostro controllo); il Live di Milkdown (<code>.ProseMirror</code>) invece è scansionato, su una nota ricca, in tema chiaro e scuro (<code>a11y.spec</code>; per le liste vedi ADR-0049, «Stato dopo W8»); l&#39;editor espone <code>role=textbox</code>, <code>aria-multiline</code> (forniti da CodeMirror) e l&#39;etichetta tradotta &quot;Editor della nota&quot;. Il comportamento reale con gli screen reader è nella checklist manuale.</p><h3 id="esito-misurato" tabindex="-1">Esito misurato <a class="header-anchor" href="#esito-misurato" aria-label="Permalink to &quot;Esito misurato&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Regola axe (impatto)</th><th>Prima</th><th>Dopo</th><th>Correzione</th></tr></thead><tbody><tr><td><code>nested-interactive</code> (serious)</td><td>18 occorrenze (schede dei documenti, tab della base e del grafo)</td><td>0</td><td>La scheda è ora <code>button role=tab</code> con il pulsante di chiusura <strong>fuori</strong> dal ruolo <code>tab</code>; il tablist contiene solo schede.</td></tr><tr><td><code>aria-input-field-name</code> (serious)</td><td>2</td><td>0</td><td>Palette e selettore: <code>combobox</code> + <code>listbox</code> etichettato, <code>aria-activedescendant</code>, <code>aria-controls</code>.</td></tr><tr><td><code>scrollable-region-focusable</code> (serious)</td><td>2</td><td>0</td><td>Il listbox scorrevole è focalizzabile (<code>tabindex=-1</code>) senza entrare nell&#39;ordine di tabulazione.</td></tr><tr><td><code>color-contrast</code> (serious)</td><td>4 (testo secondario nei risultati, filtri della base, link in tema scuro)</td><td>0</td><td>Nuovi token <code>--text-muted</code>/<code>--text-faint</code> (≥4,5:1 su tutte le superfici, chiaro e scuro) e <code>--accent-text</code> per i link.</td></tr><tr><td><code>aria-required-children</code> (critical)</td><td>introdotta e risolta durante la correzione</td><td>0</td><td>Tablist in un contenitore dedicato; spazio e pulsanti accessori fuori dal tablist.</td></tr></tbody></table><p>Totale dopo le correzioni: <strong>0 violazioni</strong> (di qualunque impatto) in 20 scansioni (10 scenari × 2 temi).</p><p><strong>Palette di Clarae notanda (1.5, ADR-0052).</strong> I colori hanno una sola fonte, i token <code>--brand-*</code> di <code>packages/ui/src/tokens.css</code>, da cui derivano quelli del workbench (<code>packages/workbench/src/styles/tokens.css</code>: <code>--accent</code> per testo e riempimenti, <code>--accent-bright</code> per ciò che non è testo, <code>--accent-text</code>, <code>--text-muted</code>, <code>--text-faint</code>). Il Teal del marchio da solo non regge il testo (3,5:1 su bianco), per questo <code>--accent</code> ne usa una tonalità più scura. <code>packages/workbench/src/styles/tokens.contrast.test.ts</code> impone un contrasto di almeno 4,5:1 tra testo e superficie nei due temi; la tabella sopra è la misura axe fatta prima del cambio di palette e non è stata rifatta in questo passo.</p><h2 id="interventi-di-accessibilita-dell-app-non-solo-test" tabindex="-1">Interventi di accessibilità dell&#39;app (non solo test) <a class="header-anchor" href="#interventi-di-accessibilita-dell-app-non-solo-test" aria-label="Permalink to &quot;Interventi di accessibilità dell&#39;app (non solo test)&quot;">​</a></h2><ul><li><strong>Albero dei file:</strong> <code>role=tree</code>/<code>treeitem</code> con <code>aria-level</code>, <code>aria-expanded</code>, <code>aria-selected</code>; roving tabindex; frecce, <code>Home</code>/<code>End</code>, <code>→</code>/<code>←</code>, <code>Invio</code>/<code>Spazio</code>, <code>F2</code> (rinomina), <code>Canc</code> (cestino), tasto Menu / <code>Maiusc+F10</code> (menu contestuale).</li><li><strong>Schede</strong> (barra laterale e documenti): roving tabindex e frecce; <code>Canc</code> chiude la scheda del documento.</li><li><strong>Menu contestuale:</strong> il focus entra nel menu all&#39;apertura, frecce/<code>Home</code>/<code>End</code>, <code>Esc</code>/<code>Tab</code> chiudono e il focus torna all&#39;origine.</li><li><strong>Palette e selettore rapido:</strong> pattern combobox/listbox.</li><li><strong>Stato di sincronizzazione:</strong> regione <code>role=status</code> (<code>aria-live=polite</code>) nel blocco di stato del vault (footer della barra destra, o intestazione a barra chiusa).</li><li><strong>Barra di stato facoltativa</strong> (ADR-0035): <code>role=status</code> <strong>senza</strong> <code>aria-live</code>, perché annunciare i conteggi a ogni tasto sarebbe rumore; il pulsante della modalità ha un nome accessibile («Modalità: Live. Clic per cambiare»). La scansione axe della shell la accende (scenario «status bar», <code>e2e/a11y.spec.ts</code>).</li><li><strong>Focus visibile</strong> ovunque (<code>:focus-visible</code>), <strong>colori forzati</strong> (<code>forced-colors: active</code>: focus, scheda attiva e voce selezionata con i colori di sistema) e <strong>movimento ridotto</strong> (<code>prefers-reduced-motion</code>).</li><li><code>&lt;html lang&gt;</code> segue la lingua scelta; stringhe prima fisse in inglese (titolo &quot;Error&quot;, etichetta dell&#39;editor) spostate in i18n.</li></ul><h2 id="limiti-noti-da-fare" tabindex="-1">Limiti noti / da fare <a class="header-anchor" href="#limiti-noti-da-fare" aria-label="Permalink to &quot;Limiti noti / da fare&quot;">​</a></h2><ul><li>Grafo e lavagna sono superfici grafiche senza equivalente testuale completo (il grafo ha stato <code>aria-live</code>, ma non una navigazione per nodi). Da progettare dopo la 1.0. Per i <strong>disegni</strong> il comando «Descrivi il disegno come testo» elenca contenuto, cornici, testi e link in un dialogo navigabile; la canvas di Excalidraw resta esclusa dalla scansione axe, ma barra, esportazione, pannello Strumenti, dialoghi LaTeX e Mermaid, descrizione e presentazione sono scansionati (<code>e2e/a11y.spec.ts</code>).</li><li>Dialog dell&#39;app (<code>ui/dialogs.tsx</code>): il comportamento di focus è coperto dai test unitari esistenti; la verifica con screen reader è manuale.</li><li>Il pulsante &quot;✕&quot; di chiusura delle schede è nascosto agli screen reader (<code>aria-hidden</code>, <code>tabindex=-1</code>) per rispettare il pattern tab: la chiusura da tastiera è <code>Canc</code> e dal menu della scheda.</li><li>Nessuna verifica con VoiceOver/NVDA/Orca reali è stata fatta in questo ciclo; i webview reali (WKWebView, WebView2, WebKitGTK) differiscono da Chromium.</li></ul><h2 id="checklist-manuale-non-spuntata-—-per-ogni-os" tabindex="-1">Checklist manuale (non spuntata) — per ogni OS <a class="header-anchor" href="#checklist-manuale-non-spuntata-—-per-ogni-os" aria-label="Permalink to &quot;Checklist manuale (non spuntata) — per ogni OS&quot;">​</a></h2><p>Ambienti: <strong>macOS</strong> con VoiceOver su WKWebView; <strong>Windows</strong> con NVDA (e Narrator) su WebView2; <strong>Linux</strong> con Orca su WebKitGTK. Annotare versione OS/screen reader e data.</p><p>Generale (tutti gli OS)</p><ul><li>[ ] L&#39;app si avvia e annuncia titolo della finestra e regione principale; la lingua di sintesi corrisponde alla lingua dell&#39;interfaccia.</li><li>[ ] Schermata di benvenuto: pulsante &quot;Apri cartella come vault&quot; e vault recenti annunciati e attivabili.</li><li>[ ] Barra laterale: le schede (File/Struttura a sinistra; Proprietà/Tag/Link/Slide/Statistiche a destra, solo icona) sono annunciate col loro nome come &quot;scheda, selezionata, n di m&quot;; le frecce cambiano scheda.</li><li>[ ] Albero dei file: annuncia nome, livello, &quot;espanso/compresso&quot; e posizione; <code>→</code>/<code>←</code> espande/chiude; <code>Invio</code> apre la nota; <code>F2</code> apre la richiesta di nome; menu da tasto Menu/<code>Maiusc+F10</code> navigabile.</li><li>[ ] Schede dei documenti: annunciate con il nome della nota; frecce e <code>Canc</code> funzionano; la nota attiva è chiara.</li><li>[ ] Editor: il campo è annunciato come &quot;Editor della nota, modifica, più righe&quot;; si legge riga per riga; i caratteri digitati e le righe sono annunciati; le scorciatoie di formattazione non confliggono con quelle del screen reader.</li><li>[ ] Live (editor Milkdown, dal 2026-11-12 l&#39;unico): elenchi (con il numero di voci), caselle dei task («Task: testo»), titoli, link, callout e tabelle sono comprensibili; la barra sulla selezione e il tooltip dei link hanno un nome e si annunciano; il menu <code>/</code> si annuncia; il «+» della maniglia ha un nome (la presa è nascosta ai lettori di schermo: usare <code>/</code> e <code>Alt+↑/↓</code>); il passaggio alla modalità sorgente e lettura è annunciato. <strong>Non ancora provato con VoiceOver, NVDA e Orca</strong> (seguito aperto di ADR-0049, A-W8).</li><li>[ ] Palette comandi e selettore rapido: all&#39;apertura il campo è annunciato come &quot;casella combinata&quot;; spostando la selezione con le frecce si legge la voce; <code>Invio</code> esegue; <code>Esc</code> chiude e il focus torna all&#39;editor.</li><li>[ ] Dialog (conferme, richieste di nome, errori): titolo annunciato, focus dentro, <code>Esc</code> chiude, il focus torna all&#39;origine.</li><li>[ ] Stato del vault (footer della barra destra): i cambi di sincronizzazione (sincronizzato → in corso → offline/errore) sono annunciati senza rubare il focus; il badge del permesso (lettore/editor) è letto.</li><li>[ ] Impostazioni: ogni controllo ha etichetta; le impostazioni bloccate dall&#39;amministratore annunciano il motivo.</li><li>[ ] Procedure guidate (collega al cloud, importer): passi annunciati (&quot;Passo n di m&quot;), errori e avanzamento annunciati; passphrase, forza della passphrase e chiave di recupero comprensibili; il campo passphrase non rivela il contenuto.</li><li>[ ] Condivisione e inviti: elenco destinatari e livelli leggibili; accettare/rifiutare un invito è possibile da tastiera.</li><li>[ ] Recupero file / cronologia: elenco delle versioni e diff leggibili; &quot;Ripristina&quot; è chiaramente un&#39;azione.</li><li>[ ] Vista grafo e lavagna: l&#39;utente è informato che non hanno equivalente testuale completo e trova un&#39;alternativa (backlink, struttura, note incorporate).</li><li>[ ] Contrasto elevato / colori forzati: testi, focus, scheda attiva e selezione sono visibili (Windows: tema &quot;Contrasto elevato&quot;).</li><li>[ ] &quot;Riduci movimento&quot; del sistema: nessuna animazione residua.</li><li>[ ] Zoom dell&#39;interfaccia (Impostazioni → Aspetto) al massimo: nessun contenuto tagliato nelle finestre principali.</li></ul><p>Specifico per OS</p><ul><li>[ ] <strong>macOS/VoiceOver:</strong> il rotore elenca intestazioni, link e controlli moduli; Safari/WKWebView non intercetta <code>Mod+,</code> e le scorciatoie dell&#39;app.</li><li>[ ] <strong>Windows/NVDA:</strong> modalità focus/modalità navigazione si alternano correttamente nell&#39;editor e nelle liste; Narrator: stessa verifica sui dialog.</li><li>[ ] <strong>Linux/Orca:</strong> il webview espone l&#39;albero di accessibilità (AT-SPI abilitato); controllare albero dei file, dialog e palette.</li></ul>',20)])])}const g=o(n,[["render",c]]);export{m as __pageData,g as default};
